def integer_square_root(n, k=2):
    if n == 0:
        return 0
    if n < 0:
        return -integer_square_root(-n, k) if k & 1 else None
    u = 1 << -(-n.bit_length() // k)
    s = u + 1
    while u < s:
        s = u
        t = (k - 1) * s + n // s ** (k - 1)
        u = t // k
    return s

