def coin_change(coins, amount):
    if amount == 0:
        return 0
    if len(coins) == 0:
        return -1
    max_value = amount + 1
    dp = [max_value for i in range(max_value)]
    dp[0] = 0
    for i in range(1, max_value):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    if dp[amount] == max_value:
        return -1
    return dp[amount]

def group_anagrams(strings: list[str]) -> list[list[str]]:
