        while left and right:
            if left[0] <= right[0]:
                merged.append(left.pop(0))
            else:
                merged.append(right.pop(0))
        merged.extend(left)
        merged.extend(right)
        return merged
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def n_queens(n):
    def is_safe(row, col):
        for i in range(row):
            if col == cols[i] or abs(row - i) == abs(col - cols[i]):
                return False
        return True
    def solve(row, cols):
        if row == n:
            solutions.append(cols[:])
            return
        for col in range(n):
            if is_safe(row, col):
                cols[row] = col
                solve(row + 1, cols)
                cols[row] = -1
    solutions = []
    cols = [-1] * n
    solve(0, cols)
    return solutions

def radix_sort(nums):
