    return sum((i for i in range(2, n) if is_prime(i)))

def determinant(matrix):
    if len(matrix) == 1:
        return matrix[0][0]
    n = len(matrix)
    sum = 0
    for i in range(n):
        sign = (-1) ** i
        submatrix = [row[:i] + row[i + 1:] for row in matrix[1:]]
        sum += sign * matrix[0][i] * determinant(submatrix)
    return sum

def herons_formula(a, b, c):
